INSERT INTO learning_materials(node_slug, title, provider, material_type, url, start_url, language, is_primary, cover_label, cover_text, cover_theme, description, overview, sort_order) VALUES
('ai-literacy', 'Elements of AI · Introduction to AI', 'University of Helsinki / MinnaLearn', 'course', 'https://www.elementsofai.com/', 'https://www.elementsofai.com/', 'en', 1, 'CORE', 'AI 通识', 'g-purple', '面向非技术背景学习者的人工智能入门课程，适合建立概念、能力边界和应用场景认知。', '这份主资料从「AI 是什么」开始，逐步解释问题求解、机器学习、神经网络与社会影响。它不要求编程背景，适合作为学习路线的第一站。学完后，你应该能区分 AI、机器学习和深度学习，理解 AI 能力来自数据、模型和目标函数，而不是魔法。', 10),
('python', 'The Python Tutorial', 'Python Software Foundation', 'documentation', 'https://docs.python.org/3/tutorial/', 'https://docs.python.org/3/tutorial/introduction.html', 'en', 1, 'PY', 'Python', 'g-green', 'Python 官方教程，覆盖语法、数据结构、模块、输入输出、异常和类等基础。', '官方教程适合建立可长期使用的 Python 语法底座。它不像速成文章那样只列语法点，而是按语言能力递进组织：先写表达式和控制流，再学习数据结构、模块化、文件和异常处理。完成本节点后，你应能阅读和编写基础 Python 脚本，并为后续机器学习代码做准备。', 10),
('math-foundation', 'Mathematics for Machine Learning', 'Marc Peter Deisenroth / A. Aldo Faisal / Cheng Soon Ong', 'book', 'https://mml-book.github.io/', 'https://mml-book.github.io/book/mml-book.pdf', 'en', 1, 'MATH', '数学', 'g-yellow', '机器学习数学基础教材，聚焦线性代数、解析几何、矩阵分解、概率与优化。', '这份资料把机器学习需要的数学工具集中在一本书里，不追求覆盖所有数学分支，而是解释模型训练中最常见的线性代数、概率、优化和矩阵概念。学习目标不是做证明竞赛，而是能看懂向量、矩阵、梯度、分布和损失函数。', 10),
('machine-learning', 'Machine Learning Crash Course', 'Google for Developers', 'course', 'https://developers.google.com/machine-learning/crash-course', 'https://developers.google.com/machine-learning/crash-course', 'en', 1, 'FUND', 'ML', 'g-pink', 'Google 面向开发者的机器学习速成课程，覆盖监督学习、数据、训练与评估基础。', '这门课程适合把零散概念整理成机器学习工作流：问题定义、数据表示、模型训练、损失函数、泛化和评估。它包含短讲解和练习，适合在学完 AI 通识、Python 和基础数学后进入。', 10),
('supervised-learning', 'Supervised Learning · Machine Learning Crash Course', 'Google for Developers', 'course', 'https://developers.google.com/machine-learning/crash-course', 'https://developers.google.com/machine-learning/crash-course/linear-regression', 'en', 1, 'SUP', '监督', 'g-warm', '以线性回归、分类、特征和损失为主线理解监督学习。', '监督学习的核心是用带标签样本学习输入到输出的映射。主资料通过回归和分类任务解释标签、特征、损失、梯度下降和泛化。完成后你应能判断一个问题是否适合监督学习，并理解训练集、验证集和测试集各自的作用。', 10),
('unsupervised-learning', 'Clustering · Machine Learning Crash Course', 'Google for Developers', 'course', 'https://developers.google.com/machine-learning/clustering', 'https://developers.google.com/machine-learning/clustering/overview', 'en', 1, 'UNSUP', '无监督', 'g-yellow', 'Google 聚类课程，讲解无监督学习中的相似度、聚类流程和评估。', '无监督学习关注没有标签时如何发现结构。主资料用聚类作为入口，解释相似度、特征缩放、聚类算法和结果解释。学完后你应能把无监督学习理解为探索数据结构的工具，而不是替代监督学习的万能方法。', 10),
('training-evaluation', 'Rules of Machine Learning', 'Google for Developers', 'guide', 'https://developers.google.com/machine-learning/guides/rules-of-ml', 'https://developers.google.com/machine-learning/guides/rules-of-ml', 'en', 1, 'EVAL', '评估', 'g-warm', 'Google 的机器学习工程经验指南，聚焦上线前后的评估、特征、数据和目标设计。', '训练评估节点关注模型是否真的有用。主资料强调先建立简单基线、定义可靠指标、检查数据管道、避免训练服务偏差，并持续观察真实业务目标。它适合把模型训练从 notebook 推向工程实践前阅读。', 10),
('neural-network', 'Dive into Deep Learning · Multilayer Perceptrons', 'Dive into Deep Learning', 'book', 'https://d2l.ai/', 'https://d2l.ai/chapter_multilayer-perceptrons/index.html', 'en', 1, 'DEEP', 'NN', 'g-cyan', '开源深度学习教材，使用可运行代码解释多层感知机、反向传播和训练。', '神经网络节点从多层感知机开始理解深度学习。主资料用代码和图示解释层、激活函数、损失、反向传播、过拟合和正则化。完成后你应能把神经网络看作可组合函数，而不是黑盒术语。', 10),
('embedding', 'Embeddings Guide', 'OpenAI Platform Docs', 'documentation', 'https://platform.openai.com/docs/guides/embeddings', 'https://platform.openai.com/docs/guides/embeddings', 'en', 1, 'VEC', 'Embedding', 'g-green', 'OpenAI 官方 Embeddings 指南，解释向量表示、相似度搜索和常见应用。', 'Embedding 节点解释如何把文本、图像等内容转成可比较的向量。主资料聚焦嵌入模型的输入输出、距离度量、语义搜索、聚类和推荐。完成后你应能理解向量库、RAG 和语义检索为什么需要 Embedding。', 10),
('transformer', 'Transformers · Hugging Face NLP Course', 'Hugging Face', 'course', 'https://huggingface.co/learn/nlp-course/chapter1/4', 'https://huggingface.co/learn/nlp-course/chapter1/4', 'en', 1, 'TR', 'Transformer', 'g-cyan', 'Hugging Face NLP 课程中的 Transformer 章节，介绍架构、任务类型和 pipeline。', 'Transformer 节点建立大模型架构基础。主资料用 NLP 任务和 pipeline 解释 encoder、decoder、attention 与预训练模型如何服务分类、生成、问答等任务。完成后你应能理解为什么 Transformer 成为大语言模型的核心结构。', 10),
('llm-foundation', 'Hugging Face LLM Course', 'Hugging Face', 'course', 'https://huggingface.co/learn/llm-course/chapter1/1', 'https://huggingface.co/learn/llm-course/chapter1/1', 'en', 1, 'LLM', 'LLM', 'g-green', 'Hugging Face 大语言模型课程，覆盖 LLM 概念、token、推理、微调和应用。', 'LLM 基础节点把 Transformer 知识推进到大语言模型。主资料解释模型、tokenizer、上下文窗口、生成参数、推理限制和应用方式。完成后你应能阅读 LLM API 文档，并理解提示、上下文和模型输出之间的关系。', 10),
('fine-tuning-eval', 'Fine-tuning Guide', 'OpenAI Platform Docs', 'documentation', 'https://platform.openai.com/docs/guides/fine-tuning', 'https://platform.openai.com/docs/guides/fine-tuning', 'en', 1, 'SFT', '微调', 'g-warm', 'OpenAI 官方微调指南，解释数据准备、训练、评估和适用场景。', '微调评测节点关注什么时候需要训练，以及怎样判断训练是否值得。主资料解释微调适合稳定格式、风格或任务偏好的场景，但不适合替代知识更新。学习重点是数据质量、训练集划分、评估样例和上线前对比。', 10),
('prompt', 'Prompt Engineering Guide', 'OpenAI Platform Docs', 'documentation', 'https://platform.openai.com/docs/guides/prompt-engineering', 'https://platform.openai.com/docs/guides/prompt-engineering', 'en', 1, 'PRMT', 'Prompt', 'g-warm', 'OpenAI 官方提示工程指南，介绍清晰指令、上下文、示例和结构化输出。', 'Prompt 节点把模型能力转化为可控输出。主资料强调写清任务、提供必要上下文、拆解复杂问题、给出示例、约束输出格式。完成后你应能把模糊需求改写成稳定提示，并知道哪些问题应通过工具或 RAG 解决。', 10),
('rag', 'Build a Retrieval Augmented Generation App', 'LangChain Docs', 'tutorial', 'https://python.langchain.com/docs/tutorials/rag/', 'https://python.langchain.com/docs/tutorials/rag/', 'en', 1, 'RAG', 'RAG', 'g-yellow', 'LangChain RAG 教程，演示加载文档、切分、向量检索和生成回答。', 'RAG 节点解决模型不知道或不能直接记住的问题。主资料按工程流程讲解文档加载、文本切分、Embedding、向量检索、上下文拼接和生成。完成后你应能解释 RAG 的每个环节，以及哪些质量问题来自检索而不是模型。', 10),
('agent', 'Agents Guide', 'OpenAI Platform Docs', 'documentation', 'https://platform.openai.com/docs/guides/agents', 'https://platform.openai.com/docs/guides/agents', 'en', 1, 'AGT', 'Agent', 'g-purple', 'OpenAI Agents 指南，覆盖工具调用、任务编排、状态和安全边界。', 'Agent 节点关注模型如何规划并调用工具完成多步骤任务。主资料帮助你理解工具定义、指令、上下文、执行状态和安全控制。完成后你应能区分普通聊天、工具调用和 Agent 工作流。', 10),
('model-ops', 'Rules of Machine Learning', 'Google for Developers', 'guide', 'https://developers.google.com/machine-learning/guides/rules-of-ml', 'https://developers.google.com/machine-learning/guides/rules-of-ml', 'en', 1, 'OPS', '治理', 'g-warm', 'Google 机器学习工程规则，适合理解模型上线后的指标、数据漂移和维护策略。', '上线治理节点强调模型不是训练完就结束。主资料从工程经验出发说明监控、指标、数据质量、特征一致性、回滚和持续迭代。完成后你应能列出一个 AI 应用上线前后的基本检查清单。', 10);
