((SELECT id FROM learning_materials WHERE node_slug='ai-literacy' AND is_primary=1), 1, 2, 'AI 问题求解', '理解搜索、推理、概率和约束如何构成智能系统。', 45, 'https://www.elementsofai.com/', 20),
((SELECT id FROM learning_materials WHERE node_slug='ai-literacy' AND is_primary=1), 2, 1, '机器学习基础', '了解数据、训练、模型和泛化之间的关系。', 50, 'https://www.elementsofai.com/', 30),
