INSERT INTO learning_node_links(node_slug, title, description, url, link_type, accent_color, sort_order) VALUES
('ai-literacy', 'Google AI Essentials', '面向日常工作者的 AI 应用入门资料。', 'https://grow.google/ai-essentials/', 'course', '#7C5CFF', 10),
('ai-literacy', 'Google Machine Learning Glossary', '机器学习术语速查，适合配合通识学习。', 'https://developers.google.com/machine-learning/glossary', 'reference', '#5EE0FF', 20),
('python', 'Python Standard Library', '官方标准库索引，后续查 API 使用。', 'https://docs.python.org/3/library/', 'reference', '#16A34A', 10),
('math-foundation', '3Blue1Brown Linear Algebra', '线性代数可视化视频系列。', 'https://www.3blue1brown.com/topics/linear-algebra', 'video', '#FF7AC6', 10),
('machine-learning', 'Google ML Glossary', '训练、评估和特征相关术语索引。', 'https://developers.google.com/machine-learning/glossary', 'reference', '#5EE0FF', 10),
('supervised-learning', 'Scikit-learn Supervised Learning', '监督学习算法与 API 示例。', 'https://scikit-learn.org/stable/supervised_learning.html', 'reference', '#FDBA3B', 10),
('unsupervised-learning', 'Scikit-learn Clustering', '聚类算法与示例。', 'https://scikit-learn.org/stable/modules/clustering.html', 'reference', '#FDBA3B', 10),
('training-evaluation', 'Google ML Crash Course', '配合工程规则回看训练和评估基础。', 'https://developers.google.com/machine-learning/crash-course', 'course', '#4CCBEA', 10),
('neural-network', 'Neural Networks and Deep Learning', 'Michael Nielsen 的在线书，适合理解反向传播。', 'http://neuralnetworksanddeeplearning.com/', 'book', '#EB5AAF', 10),
('embedding', 'Vector Databases Guide', '了解向量数据库在语义检索中的位置。', 'https://www.pinecone.io/learn/vector-database/', 'article', '#14B8A6', 10),
('transformer', 'The Illustrated Transformer', '用图解理解 Transformer 结构。', 'https://jalammar.github.io/illustrated-transformer/', 'article', '#C084FC', 10),
('llm-foundation', 'OpenAI Text Generation Guide', '了解大模型文本生成接口和参数。', 'https://platform.openai.com/docs/guides/text-generation', 'documentation', '#7C5CFF', 10),
('fine-tuning-eval', 'OpenAI Evals', '了解评估集和自动评测思路。', 'https://github.com/openai/evals', 'reference', '#FF8A2A', 10),
('prompt', 'OpenAI Structured Outputs', '配合提示工程学习稳定结构化返回。', 'https://platform.openai.com/docs/guides/structured-outputs', 'documentation', '#7C5CFF', 10),
('rag', 'OpenAI File Search Guide', '了解托管检索能力的另一种实现方式。', 'https://platform.openai.com/docs/guides/tools-file-search', 'documentation', '#14B8A6', 10),
('agent', 'OpenAI Function Calling Guide', '理解 Agent 工具调用的底层能力。', 'https://platform.openai.com/docs/guides/function-calling', 'documentation', '#744AEF', 10),
('model-ops', 'Google Responsible AI Practices', '补充上线治理中的安全、责任和评估视角。', 'https://ai.google/responsibility/responsible-ai-practices/', 'reference', '#EF4444', 10);
INSERT INTO learning_node_links(node_slug, title, description, url, link_type, access_type, accent_color, sort_order) VALUES
('ai-literacy', 'ShowMeAI · 人工智能知识体系', '中文 AI 入门与机器学习知识地图，适合快速建立概念框架。', 'https://www.showmeai.tech/', 'course', 'cn', '#7C5CFF', 100),
('ai-literacy', 'B站检索 · 人工智能通识入门', '国内视频资源检索入口，适合寻找通识类课程与案例讲解。', 'https://search.bilibili.com/all?keyword=%E4%BA%BA%E5%B7%A5%E6%99%BA%E8%83%BD%20%E9%80%9A%E8%AF%86%20%E5%85%A5%E9%97%A8%20%E6%95%99%E7%A8%8B', 'video', 'cn', '#5EE0FF', 110),
('python', '廖雪峰 · Python 教程', '体系化中文 Python 教程，覆盖语法、函数、模块、面向对象与常用实践。', 'https://www.liaoxuefeng.com/wiki/1016959663602400', 'course', 'cn', '#16A34A', 100),
('python', 'B站检索 · 小甲鱼 Python 零基础', '适合零基础跟练的视频课程检索入口，可配合官方教程做练习。', 'https://search.bilibili.com/all?keyword=%E5%B0%8F%E7%94%B2%E9%B1%BC%20Python%20%E9%9B%B6%E5%9F%BA%E7%A1%80', 'video', 'cn', '#4ADE80', 110),
('math-foundation', 'B站检索 · 线性代数的本质', '用可视化方式补强向量、矩阵和线性变换直觉。', 'https://search.bilibili.com/all?keyword=%E7%BA%BF%E6%80%A7%E4%BB%A3%E6%95%B0%E7%9A%84%E6%9C%AC%E8%B4%A8', 'video', 'cn', '#FDBA3B', 100),
('math-foundation', 'B站检索 · 机器学习数学基础', '围绕概率论、线性代数、微积分和优化的中文课程检索入口。', 'https://search.bilibili.com/all?keyword=%E6%9C%BA%E5%99%A8%E5%AD%A6%E4%B9%A0%20%E6%95%B0%E5%AD%A6%E5%9F%BA%E7%A1%80%20%E6%A6%82%E7%8E%87%E8%AE%BA%20%E7%BA%BF%E6%80%A7%E4%BB%A3%E6%95%B0', 'video', 'cn', '#FFD56B', 110),
('machine-learning', 'ShowMeAI · 机器学习教程', '中文机器学习教程与算法图解，适合查漏补缺和复习术语。', 'https://www.showmeai.tech/', 'course', 'cn', '#4CCBEA', 100),
('machine-learning', 'B站检索 · 吴恩达机器学习中文', '经典机器学习课程的中文讲解与搬运资源检索入口。', 'https://search.bilibili.com/all?keyword=%E5%90%B4%E6%81%A9%E8%BE%BE%20%E6%9C%BA%E5%99%A8%E5%AD%A6%E4%B9%A0%20%E4%B8%AD%E6%96%87', 'video', 'cn', '#5EE0FF', 110),
('supervised-learning', 'ShowMeAI · 监督学习专题', '用中文资料理解回归、分类、特征和监督学习评估。', 'https://www.showmeai.tech/', 'course', 'cn', '#FDBA3B', 100),
('supervised-learning', 'B站检索 · 监督学习 分类 回归', '按任务类型查找分类、回归和监督学习案例讲解。', 'https://search.bilibili.com/all?keyword=%E7%9B%91%E7%9D%A3%E5%AD%A6%E4%B9%A0%20%E5%88%86%E7%B1%BB%20%E5%9B%9E%E5%BD%92%20%E6%9C%BA%E5%99%A8%E5%AD%A6%E4%B9%A0', 'video', 'cn', '#FF8A2A', 110),
('unsupervised-learning', 'ShowMeAI · 聚类与降维教程', '中文算法教程入口，适合配合聚类、降维和相似度学习。', 'https://www.showmeai.tech/', 'course', 'cn', '#FDBA3B', 100),
('unsupervised-learning', 'B站检索 · 无监督学习 聚类 降维', '国内视频课程检索入口，覆盖 KMeans、PCA、降维和聚类实践。', 'https://search.bilibili.com/all?keyword=%E6%97%A0%E7%9B%91%E7%9D%A3%E5%AD%A6%E4%B9%A0%20%E8%81%9A%E7%B1%BB%20%E9%99%8D%E7%BB%B4', 'video', 'cn', '#FFD56B', 110),
('training-evaluation', 'ShowMeAI · 模型评估与指标', '中文资料入口，适合学习准确率、召回率、F1、ROC 与误差分析。', 'https://www.showmeai.tech/', 'course', 'cn', '#EF4444', 100),
